
import os
import pandas as pd
import matplotlib.pyplot as plt

os.makedirs("results", exist_ok=True)

# Result files generated by the model scripts
result_files = {
    "MLP": "results/mlp_results.txt",
    "PCA + MLP": "results/pca_results.txt",
    "SVD + MLP": "results/svd_results.txt",
    "Autoencoder + MLP": "results/autoencoder_results.txt",
}

# Metrics to collect
metric_names = ["Accuracy", "Precision", "Recall", "F1 Score"]
models = {}

# Read metrics from result files
for model_name, file_path in result_files.items():

    if not os.path.exists(file_path):
        print(f"Warning: {file_path} not found. Skipping {model_name}.")
        continue

    metrics = {}

    with open(file_path, "r") as file:
        for line in file:
            if ":" not in line:
                continue

            key, value = line.split(":", 1)
            key = key.strip()
            value = value.strip()

            # Normalize metric names
            normalized_key = key.lower().replace("-", "").replace(" ", "")

            try:
                numeric_value = float(value)
            except ValueError:
                continue

            if normalized_key == "accuracy":
                metrics["Accuracy"] = numeric_value
            elif normalized_key == "precision":
                metrics["Precision"] = numeric_value
            elif normalized_key == "recall":
                metrics["Recall"] = numeric_value
            elif normalized_key == "f1score":
                metrics["F1 Score"] = numeric_value

    if all(metric in metrics for metric in metric_names):
        models[model_name] = metrics
    else:
        print(
            f"Warning: Required metrics missing in {file_path}. "
            f"Skipping {model_name}."
        )

# Add Perceptron results from its group-aware run
# Update these values if you rerun the Perceptron model.
models["Perceptron"] = {
    "Accuracy": 0.9953,
    "Precision": 0.9884,
    "Recall": 0.9985,
    "F1 Score": 0.9934
}

if not models:
    raise RuntimeError(
        "No model results found. Run the model training scripts first."
    )

# Create comparison DataFrame
df = pd.DataFrame(models).T
df.index.name = "Model"

print("\n--- Model Performance Comparison (Group-Aware Split) ---")
print(df.round(4).to_string())

# Save comparison table
df.to_csv("results/model_comparison.csv")

# Generate comparison chart
ax = df[metric_names].plot(
    kind="bar",
    figsize=(12, 6),
    ylim=(0.97, 1.01)
)

ax.set_title("PhishGuard AI: Model Performance Comparison")
ax.set_ylabel("Score")
ax.set_xlabel("Model")
ax.tick_params(axis="x", rotation=20)

plt.tight_layout()
plt.savefig("results/model_comparison.png", dpi=300)
plt.close()

print("\nSaved: results/model_comparison.csv")
print("Saved: results/model_comparison.png")
